import React from "react";
import { motion } from "framer-motion";
import { Link } from "react-router-dom";
import { Brain, Video, MessageCircle } from "lucide-react";

const Home = () => {
  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-900 via-blue-950 to-black text-white flex flex-col items-center justify-center px-6">
      {/* Hero Section */}
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
        className="text-center max-w-3xl"
      >
        <h1 className="text-4xl md:text-5xl font-extrabold mb-6 leading-tight">
          Empower Your Future with
          <span className="text-blue-400"> AI Interview Coaching</span>
        </h1>
        <p className="text-blue-100 text-lg mb-8">
          Practice, record, and get instant AI-powered feedback to improve your confidence and communication in interviews.
        </p>

        <Link
          to="/interview"
          className="bg-blue-600 hover:bg-blue-700 transition-all px-6 py-3 rounded-lg text-white font-medium shadow-md hover:shadow-blue-700/40"
        >
          Start Your Practice
        </Link>
      </motion.div>

      {/* Features Section */}
      <motion.div
        initial={{ opacity: 0 }}
        whileInView={{ opacity: 1 }}
        transition={{ delay: 0.3, duration: 0.8 }}
        className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-20 max-w-6xl w-full text-center"
      >
        {/* Feature 1 */}
        <motion.div
          whileHover={{ scale: 1.05 }}
          className="bg-blue-800/30 border border-blue-700/50 rounded-2xl p-6 shadow-lg backdrop-blur-sm"
        >
          <Brain size={40} className="mx-auto text-blue-400 mb-3" />
          <h3 className="text-xl font-semibold mb-2">AI-Powered Analysis</h3>
          <p className="text-blue-100 text-sm">
            Get detailed performance insights, confidence metrics, and voice tone analysis.
          </p>
        </motion.div>

        {/* Feature 2 */}
        <motion.div
          whileHover={{ scale: 1.05 }}
          className="bg-blue-800/30 border border-blue-700/50 rounded-2xl p-6 shadow-lg backdrop-blur-sm"
        >
          <Video size={40} className="mx-auto text-blue-400 mb-3" />
          <h3 className="text-xl font-semibold mb-2">Video Practice</h3>
          <p className="text-blue-100 text-sm">
            Record your responses, review them, and receive feedback to improve your body language.
          </p>
        </motion.div>

        {/* Feature 3 */}
        <motion.div
          whileHover={{ scale: 1.05 }}
          className="bg-blue-800/30 border border-blue-700/50 rounded-2xl p-6 shadow-lg backdrop-blur-sm"
        >
          <MessageCircle size={40} className="mx-auto text-blue-400 mb-3" />
          <h3 className="text-xl font-semibold mb-2">Personalized Feedback</h3>
          <p className="text-blue-100 text-sm">
            Receive actionable feedback from AI to refine your communication and confidence.
          </p>
        </motion.div>
      </motion.div>

      {/* CTA Section */}
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        whileInView={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.5, duration: 0.8 }}
        className="mt-20 text-center"
      >
        <h2 className="text-2xl font-bold mb-4">
          Ready to Ace Your Next Interview?
        </h2>
        <Link
          to="/signup"
          className="bg-blue-500 hover:bg-blue-600 transition-all px-6 py-3 rounded-lg text-white font-medium shadow-md hover:shadow-blue-700/40"
        >
          Join Now
        </Link>
      </motion.div>
    </div>
  );
};

export default Home;
